describe('ToolRegistry', () => {
  it('rejects input missing a required property without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    const executor = async () => {
      executorCalls += 1;
      return 'sunny';
    };
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      executor
    );

    const response = await registry.execute('get_weather', {});

    expect({mentionsLocation: /location/.test(response.result), mentionsRequired: /required/i.test(response.result), executorCalls}).toEqual({
      mentionsLocation: true,
      mentionsRequired: true,
      executorCalls: 0,
    });
  });
});
